  "third-eye-chakra": { width: 1500, height: 1128 },
  "crown-chakra": { width: 1500, height: 1128 },
  "tetragrammaton": { width: 1200, height: 902 },
  "merkaba": { width: 1500, height: 1128 },
  "tetra": { width: 1500, height: 1128 },
  "higher-access": { width: 1500, height: 1041 },
  "vehicular-dynamics": { width: 1000, height: 752 },
  "external-womb": { width: 1100, height: 827 },
  "recursive-pantheism": { width: 1064, height: 800 },
  "cosmic-egg": { width: 1000, height: 1330 },
  "vortex-dynamics": { width: 1250, height: 940 },
  "vitruvian-spirit": { width: 2783, height: 1800 },
  "prismatic-equation": { width: 1000, height: 1000 },
  "trinary-transcendence": { width: 1100, height: 1100 },
