  "translinguistic-equation": { width: 1000, height: 1000 },
  "immaculate-conception": { width: 773, height: 1000 },
  "twilight-pantheism": { width: 1000, height: 752 },
  "caelestis-lupus": { width: 1000, height: 1000 },
